from collections import Counter
corpus = {("d", "a", "t", "a"): 4, ("d", "a", "t", "e"): 3, ("g", "a", "t", "e"): 2}
merges = []
for _ in range(3):
    pairs = Counter()
    for w, f in corpus.items():
        for p in zip(w, w[1:]):
            pairs[p] += f
    a, b = max(pairs, key=pairs.get)
    merges.append(a + b)
    new = {}
    for w, f in corpus.items():
        out, i = [], 0
        while i < len(w):
            if i + 1 < len(w) and (w[i], w[i + 1]) == (a, b):
                out.append(a + b)
                i += 2
            else:
                out.append(w[i])
                i += 1
        new[tuple(out)] = f
    corpus = new
print(merges)   # ['at', 'dat', 'data']
